        const originalApplyUnavailableDates = App.Http.Booking.applyUnavailableDates;
        App.Http.Booking.applyUnavailableDates = function(unavailableDates, selectedDateString, setDate) {
            originalApplyUnavailableDates.call(this, unavailableDates, selectedDateString, setDate);
            // If we just set date due to month change and user had typed a valid date, restore it
            if (setDate && !vars('manage_mode')) {
                const $input = $selectDate;
                const currentVal = $input.val();
                if (currentVal) {
                    const parsed = moment(currentVal, App.Utils.UI.getDateFormat());
                    if (parsed.isValid()) {
                        const currentString = parsed.format('YYYY-MM-DD');
                        if (unavailableDates.indexOf(currentString) === -1) {
                            // User's date is available, restore it
                            App.Utils.UI.setDateTimePickerValue($input, parsed.toDate());
                            App.Http.Booking.getAvailableHours(currentString);
                            App.Pages.Booking.updateConfirmFrame();
